function normalize(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/\s+/g,' ');}
function blitzLimit(streak){return Math.max(BLITZ_MIN_MS,Math.round(BLITZ_BASE_MS-Math.sqrt(Math.max(0,streak))*280));}
