function accepts(given,answers){return (Array.isArray(answers)?answers:[answers]).some(answer=>normalize(answer)===normalize(given));}
function alienPool(turn){const tier=Math.min(4,1+Math.floor(turn/4));return ALIEN.filter(item=>item.tier<=tier);}
